	@Test
	@Timeout(value = 30, unit = TimeUnit.SECONDS)
	void listenerRollbackReentryDoesNotRedeliverSuccessfulCommit(@TempDir Path directory) throws Exception {
		LmdbStoreConfig config = smallMapConfig();
		CountingLmdbStore store = new CountingLmdbStore(directory.toFile(), config);
		SailRepository repository = new SailRepository(store);
		List<Statement> statements = replayStatements(3);
		AtomicReference<RepositoryConnection> writerReference = new AtomicReference<>();
		AtomicInteger notifications = new AtomicInteger();
		AtomicInteger addedEvents = new AtomicInteger();
		AtomicInteger removedEvents = new AtomicInteger();
		AtomicInteger rollbackCallbacks = new AtomicInteger();
		AtomicInteger completedRollbacks = new AtomicInteger();
		AtomicReference<RuntimeException> rollbackFailure = new AtomicReference<>();
		AtomicBoolean failListenerOnce = new AtomicBoolean(true);
		RuntimeException listenerFailure = new IllegalStateException(
				"injected listener failure after rollback reentry");
		Throwable commitFailure = null;
		Set<Statement> immediatelyVisibleStatements = Set.of();
		String immediatelyVisibleNamespace = null;
		Set<Statement> persistedStatements = Set.of();
		String persistedNamespace = null;
		long nativeCommitGenerationBefore = 0L;
		long nativeCommitGenerationAfter = 0L;

		try {
			repository.init();
			store.getBackingStore().enableMultiThreading = false;
			store.probe.reset();
			store.addSailChangedListener(event -> {
				notifications.incrementAndGet();
				if (event.statementsAdded()) {
					addedEvents.incrementAndGet();
				}
				if (event.statementsRemoved()) {
					removedEvents.incrementAndGet();
				}
				if (failListenerOnce.compareAndSet(true, false)) {
					rollbackCallbacks.incrementAndGet();
					try {
						writerReference.get().rollback();
						completedRollbacks.incrementAndGet();
					} catch (RuntimeException failure) {
						rollbackFailure.set(failure);
					}
					throw listenerFailure;
				}
			});

			CountingTripleStore tripleStore = store.probe.tripleStore.get();
			assertNotNull(tripleStore, "The injected TripleStore must be available for its native commit receipt");
			nativeCommitGenerationBefore = tripleStore.getNativeCommitGeneration();
			try (RepositoryConnection writer = repository.getConnection();
					RepositoryConnection observer = repository.getConnection()) {
				writerReference.set(writer);
				writer.begin(IsolationLevels.SNAPSHOT_READ);
				addStatements(writer, statements);
				writer.setNamespace("m3", "urn:m3:");
				try {
					writer.commit();
				} catch (RuntimeException failure) {
					commitFailure = failure;
				}
				nativeCommitGenerationAfter = tripleStore.getNativeCommitGeneration();
				immediatelyVisibleStatements = readAllStatements(observer);
				immediatelyVisibleNamespace = observer.getNamespace("m3");
			}
		} finally {
			repository.shutDown();
		}

		SailRepository reopened = new SailRepository(new LmdbStore(directory.toFile(), config));
		try {
			reopened.init();
			try (RepositoryConnection reader = reopened.getConnection()) {
				persistedStatements = readAllStatements(reader);
				persistedNamespace = reader.getNamespace("m3");
			}
		} finally {
			reopened.shutDown();
		}

		Set<Statement> expectedStatements = Set.copyOf(statements);
		Throwable observedCommitFailure = commitFailure;
		long observedNativeCommitGenerationBefore = nativeCommitGenerationBefore;
		long observedNativeCommitGenerationAfter = nativeCommitGenerationAfter;
		Set<Statement> observedImmediateStatements = immediatelyVisibleStatements;
		String observedImmediateNamespace = immediatelyVisibleNamespace;
		Set<Statement> observedPersistedStatements = persistedStatements;
		String observedPersistedNamespace = persistedNamespace;
		int observedNotifications = notifications.get();
		int observedAddedEvents = addedEvents.get();
		int observedRemovedEvents = removedEvents.get();
		assertAll("same-thread listener rollback must not erase or redeliver a native commit",
				() -> assertEquals(1, rollbackCallbacks.get(), "the listener rollback callback must activate once"),
				() -> assertEquals(1, completedRollbacks.get(), "the listener rollback must complete before it throws"),
				() -> assertNull(rollbackFailure.get(), "the supported reentrant rollback must not fail"),
				() -> assertTrue(causeChainContainsIdentity(observedCommitFailure, listenerFailure),
						"the exact listener exception must reach the commit caller"),
				() -> assertTrue(observedNativeCommitGenerationAfter > observedNativeCommitGenerationBefore,
						"the successful native commit must be authoritative before listener reentry"),
				() -> assertEquals(expectedStatements, observedImmediateStatements,
						"the committed statements must be visible despite listener rollback and failure"),
				() -> assertEquals("urn:m3:", observedImmediateNamespace),
				() -> assertEquals(1, observedNotifications,
						"rollback and connection close must not redeliver the event"),
				() -> assertEquals(1, observedAddedEvents),
				() -> assertEquals(0, observedRemovedEvents),
				() -> assertEquals(1, store.probe.transactionStarts.get(),
						"successful native commit must not replay after listener failure"),
				() -> assertEquals(0, store.probe.journalAllocations.get(),
						"the covered transaction must remain journal-free"),
				() -> assertEquals(expectedStatements, observedPersistedStatements,
						"the successful native commit must survive reopening exactly"),
				() -> assertEquals("urn:m3:", observedPersistedNamespace));
	}

	@Test
	void commitMapFullStartsFreshAttemptWithoutMutationJournal(@TempDir Path directory) throws Exception {
		LmdbStoreConfig config = smallMapConfig();
		CountingLmdbStore store = new CountingLmdbStore(directory.toFile(), config);
		SailRepository repository = new SailRepository(store);
		List<Statement> statements = replayStatements(3);
		try {
			repository.init();
			store.getBackingStore().enableMultiThreading = false;
			store.probe.reset();
			store.probe.failNextCommit.set(true);
			try (RepositoryConnection writer = repository.getConnection();
					RepositoryConnection observer = repository.getConnection()) {
				writer.begin(IsolationLevels.SNAPSHOT_READ);
				addStatements(writer, statements);
				writer.setNamespace("m3", "urn:m3:");
				RuntimeException commitFailure = null;
				try {
					writer.commit();
				} catch (RuntimeException failure) {
					commitFailure = failure;
				}

				assertEquals(1, store.probe.injectedCommitFailures.get(),
						"The native commit-capacity failure injection must activate");
				assertNull(commitFailure,
						"A frozen commit must recover from the injected native commit-capacity failure: "
								+ commitFailure);
				assertStatementsPresent(observer, statements);
				assertEquals("urn:m3:", observer.getNamespace("m3"));
			}
		} finally {
			repository.shutDown();
		}

		assertPersisted(directory, config, statements);
		assertAll("the recovered commit uses a new physical attempt without a mutation journal",
				() -> assertEquals(2, store.probe.transactionStarts.get(),
						"the failed commit and retry must each start through the public-attempt entry point"),
				() -> assertEquals(0, store.probe.journalAllocations.get(),
						"a covered frozen retry must not allocate a whole-transaction mutation journal"));
	}

